const fs = require('node:fs'), cp = require('node:child_process'), assert = require('node:assert/strict');
const {chromium} = require('<PLAYWRIGHT_MODULE>');
const root = '<EASYSTUD_SOURCE_ROOT>';
const runId = 'codex1-k1680-tail-f25i-native', out = __dirname;
const ps = (file, args) => cp.execFileSync('powershell.exe', ['-NoProfile', '-File', '<ORCHESTRATION_SCRIPTS>/' + file, ...args], {encoding: 'utf8'});
const css = file => fs.readFileSync(file, 'utf8').replace(/url\((["']?)(\.\.?\/[^)"']+)\1\)/g,
    (match, quote, relative) => 'url("' + new URL(relative, 'http://localhost:8051/local/groupimport/styles/student-management.css').href + '")');
async function settle(locator) {
    await locator.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(r)))));
    await locator.evaluate(async node => {
        const animations = [...node.getAnimations({subtree:true})];
        for (let n = node; n; n = n.parentElement) animations.push(...n.getAnimations());
        await Promise.all(animations.filter(a => Number.isFinite(a.effect.getTiming().iterations)).map(a => a.finished.catch(() => {})));
    });
}
async function measure(locator) {
 return locator.evaluate(node=>{
  const m=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,padding:s.padding,radius:s.borderRadius,background:s.backgroundColor,border:s.border,shadow:s.boxShadow,color:s.color,fontSize:s.fontSize,lineHeight:s.lineHeight,clip:s.clip,position:s.position,whiteSpace:s.whiteSpace,borderLeft:s.borderLeft,borderTop:s.borderTop,borderRight:s.borderRight,borderBottom:s.borderBottom,beforeBackground:getComputedStyle(n,'::before').backgroundColor,afterBackground:getComputedStyle(n,'::after').backgroundColor};};
  const avatarCentres=[...node.querySelectorAll('.local-groupimport-easystud-user__avatar .userinitials')].filter(n=>n.getClientRects().length&&getComputedStyle(n).visibility==='visible').map(n=>{const h=n.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(n);const g=range.getBoundingClientRect();return {x:g.x+g.width/2-h.x-h.width/2,y:g.y+g.height/2-h.y-h.height/2};});return {avatarCentres,frame:m(node),parts:[...node.querySelectorAll('.local-groupimport-easystud-user__name,.local-groupimport-easystud-group__name,.local-groupimport-easystud-grouping__name,.local-groupimport-easystud-user__avatar .userinitials,.local-groupimport-easystud-user__avatar img,.local-groupimport-easystud-member,.local-groupimport-easystud-user__email,.local-groupimport-easystud-user__rail,.local-groupimport-easystud-user__meta-label,.local-groupimport-easystud-user__meta-tags,.local-groupimport-easystud-user__primary-badge')].filter(n=>n.getClientRects().length).map(n=>({class:n.className,...m(n)}))};
 });
